-- ************************************** gold.fact_encounter
CREATE TABLE gold.fact_encounter (
  encounter_seq_key BIGINT NOT NULL CONSTRAINT pk_fact_encounter PRIMARY KEY GENERATED ALWAYS AS IDENTITY COMMENT 'System-generated surrogate key for the encounter.',
  encounter_id STRING NOT NULL COMMENT 'Identifier of the encounter from the source system.',
  patient_seq_key BIGINT NOT NULL COMMENT 'The patient who was seen. Every visit has exactly one patient.',
  provider_seq_key BIGINT NOT NULL COMMENT 'The provider who delivered the visit. Every visit has exactly one provider.',
  encounter_start_ts TIMESTAMP COMMENT 'Date and time the visit started.',
  encounter_end_ts TIMESTAMP COMMENT 'Date and time the visit ended.',
  encounter_type_cd STRING COMMENT 'Type of visit, from the approved visit type list.',
  encounter_primary_diagnosis_cd STRING COMMENT 'Primary diagnosis code for the visit (ICD-10).',
  encounter_billed_amt DECIMAL(18, 2) COMMENT 'Amount billed for the visit, in US dollars.',
  record_created_ts TIMESTAMP NOT NULL COMMENT 'When the record was created.',
  record_updated_ts TIMESTAMP COMMENT 'When the record was last updated. Null until the first update.',
  CONSTRAINT fk_fact_encounter_dim_patient FOREIGN KEY (patient_seq_key) REFERENCES gold.dim_patient (patient_seq_key),
  CONSTRAINT fk_fact_encounter_dim_provider FOREIGN KEY (provider_seq_key) REFERENCES gold.dim_provider (provider_seq_key)
)
COMMENT 'A single patient visit (encounter) with a provider, including timing, visit type, primary diagnosis and billed amount.';

